<script setup lang="ts">
import { ElTooltip } from 'element-plus/es/components/tooltip/index.mjs';
import 'element-plus/es/components/tooltip/style/css';
import PreviewDatePicker from '../../features/preview/components/PreviewDatePicker.vue';
import PreviewSelect from '../../features/preview/components/PreviewSelect.vue';
import { computed, reactive, ref, watch } from 'vue';
import { ElMessage } from 'element-plus/es/components/message/index.mjs';
import { usePreview, copy, splitText, knowledgeStatus, navigate, type KnowledgeDoc } from '../../features/preview/usePreviewStore';
import { dateOf } from '../../features/workbench/types';
import PageHeading from '../../features/preview/components/PageHeading.vue';
import TableFooter from '../../features/preview/components/TableFooter.vue';
import Icon from '../../features/workbench/components/WorkbenchIcon.vue';
const props=defineProps<{view:string}>(),s=usePreview(),search=ref(''),category=ref(''),status=ref(''),page=ref(1);
const params=new URLSearchParams(window.location.hash.split('?')[1]);
const initialCategory=Number(params.get('id'));
const dragging=ref(false),uploadedName=ref('');
if(props.view==='documents'&&s.categories.value.some(c=>c.id===initialCategory))category.value=String(initialCategory);
const editor=ref(false),editingId=ref<number|null>(null),preview=ref<string[]|null>(null),tab=ref('content'),error=ref(''),publishing=ref(false),upload=ref<HTMLInputElement|null>(null);
const form=reactive({categoryId:1,title:'',purpose:'',content:'',separator:'\\n\\n',length:500,overlap:50,start:'',end:'',enabled:true});
const catOpen=ref(false),catId=ref<number|null>(null),cat=reactive({name:'',description:''}),catError=ref('');
const chunkOpen=ref(false),chunkText=ref(''),chunkDoc=ref<number|null>(null),chunkIndex=ref(0),chunkError=ref('');
const rows=computed(()=>s.docs.value.filter(d=>`${d.title} ${d.purpose}`.includes(search.value.trim())&&(!category.value||d.categoryId===Number(category.value))&&(!status.value||knowledgeStatus(d)===status.value)));
const chunks=computed(()=>rows.value.flatMap(d=>d.chunks.map((text,index)=>({doc:d,text,index}))));
const filteredCats=computed(()=>s.categories.value.filter(c=>`${c.name} ${c.description}`.includes(search.value.trim())));
const count=computed(()=>props.view==='categories'?filteredCats.value.length:props.view==='chunks'?chunks.value.length:rows.value.length);
watch([search,category,status],()=>page.value=1);watch(()=>props.view,()=>{editor.value=false;search.value='';category.value='';status.value='';page.value=1;});
watch(()=>[form.content,form.separator,form.length,form.overlap],()=>preview.value=null,{flush:'sync'});
function localTime(value:string){if(!value)return '';const date=new Date(value);return new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function openDoc(d?:KnowledgeDoc, categoryId?:number){uploadedName.value='';editingId.value=d?.id||null;Object.assign(form,d?{categoryId:d.categoryId,title:d.title,purpose:d.purpose,content:d.content,separator:d.separator.replaceAll('\n','\\n'),length:d.length,overlap:d.overlap,start:localTime(d.start),end:localTime(d.end),enabled:d.enabled}:{categoryId:categoryId||Number(category.value)||s.categories.value[0]?.id||0,title:'',purpose:'',content:'',separator:'\\n\\n',length:500,overlap:50,start:'',end:'',enabled:true});error.value='';preview.value=null;tab.value='content';editor.value=true;}
const acceptedExtensions=/\.(md|markdown|txt|csv|tsv|json|yaml|yml|xml|log)$/i;
async function readFile(file?:File){
 if(!file)return;
 if(!acceptedExtensions.test(file.name)||file.size>2*1024*1024){error.value='请选择 2 MB 以内的纯文本文件（MD、TXT、CSV、TSV、JSON、YAML、XML、LOG）。';return;}
 try{const content=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer());if(content.includes('\0'))throw new Error();form.content=content;if(!form.title)form.title=file.name.replace(/\.[^.]+$/,'');uploadedName.value=file.name;error.value='';tab.value='content';}
 catch{error.value='文件无法作为 UTF-8 文本读取，请另存为 UTF-8 编码后上传。';}
}
async function fileSelected(event:Event){const input=event.target as HTMLInputElement;await readFile(input.files?.[0]);input.value='';}
function dropped(event:DragEvent){dragging.value=false;const files=event.dataTransfer?.files;if(files&&files.length>1){error.value='一次请选择一个知识文件。';return;}void readFile(files?.[0]);}
function parse(){if(!form.content.trim()){error.value='请先填写或上传知识正文。';return;}if(!Number.isInteger(form.length)||form.length<100||form.length>4000||!Number.isInteger(form.overlap)||form.overlap<0||form.overlap>=form.length){error.value='分段长度为 100–4000；重叠长度需小于分段长度。';return;}error.value='';preview.value=splitText(form.content,form.length,form.overlap,form.separator);tab.value='preview';}
async function publish(){if(publishing.value)return;publishing.value=true;error.value='';try{await new Promise(r=>setTimeout(r,350));s.publish({...copy(form),separator:form.separator.replaceAll('\\n','\n'),start:form.start?new Date(form.start).toISOString():'',end:form.end?new Date(form.end).toISOString():''},editingId.value||undefined);editor.value=false;ElMessage.success('知识已发布，切片与召回对象已更新');}catch(e){error.value=(e as Error).message;}finally{publishing.value=false;}}
function saveCategory(){catError.value='';if(!cat.name.trim()){catError.value='请填写知识库名称。';return;}if(s.categories.value.some(c=>c.id!==catId.value&&c.name===cat.name.trim())){catError.value='知识库名称已存在。';return;}if(catId.value)Object.assign(s.categories.value.find(c=>c.id===catId.value)!,copy(cat));else s.categories.value.push({id:Date.now(),...copy(cat)});catOpen.value=false;ElMessage.success('知识库已保存');}
function removeCategory(id:number){if(s.docs.value.some(d=>d.categoryId===id)){ElMessage.warning('知识库内还有知识，请先移动或删除内容');return;}s.categories.value=s.categories.value.filter(c=>c.id!==id);ElMessage.success('空知识库已删除');}
function restore(d:KnowledgeDoc){if(!d.previous)return;const dates={start:d.start,end:d.end};const previous=copy(d.previous);const current=copy(d);delete current.previous;Object.assign(d,previous,dates,{previous:current,updatedAt:new Date().toISOString(),author:s.wb.staff.name});ElMessage.success('已恢复上一版内容，保留当前生效与失效时间');}
function editChunk(d:KnowledgeDoc,index:number){chunkDoc.value=d.id;chunkIndex.value=index;chunkText.value=d.chunks[index];chunkError.value='';chunkOpen.value=true;}
function saveChunk(){const d=s.docs.value.find(d=>d.id===chunkDoc.value);if(!d)return;if(!chunkText.value.trim()){chunkError.value='切片内容不能为空。';return;}const previous=copy(d);delete previous.previous;d.previous=previous;d.chunks[chunkIndex.value]=chunkText.value.trim();d.updatedAt=new Date().toISOString();d.author=s.wb.staff.name;chunkOpen.value=false;ElMessage.success('切片已更新，召回测试将使用新内容');}
const vectorBusy=ref<number|null>(null);async function vector(d:KnowledgeDoc){vectorBusy.value=d.id;await new Promise(r=>setTimeout(r,600));vectorBusy.value=null;ElMessage.success('检索内容已更新');}
if(props.view==='documents'&&params.get('new')==='1')openDoc(undefined,initialCategory);
function windowNewKnowledge(id:number){window.location.hash=`/knowledge/documents?id=${id}&new=1`;}
function catName(id:number){return s.categories.value.find(c=>c.id===id)?.name||'未分类';}
</script>
<template><div class="pv-page" :class="{'pv-editor-page':editor}"><template v-if="!editor"><PageHeading :title="view==='categories'?'知识库':view==='chunks'?'知识切片':'客服知识'" :description="view==='categories'?'按用途整理知识分类，帮助客服与 AI 找到合适的内容。':view==='chunks'?'查看与维护已发布的知识片段，和文章详情使用同一份内容。':'维护店铺客服使用的知识，发布后参与当前有效知识的检索。'" eyebrow="AI 与知识"/>
<section v-if="view==='categories'" class="pv-card pv-categories-panel"><div class="pv-filters"><div class="pv-search"><Icon name="Search"/><input v-model="search" placeholder="搜索知识库名称或用途" aria-label="搜索知识库"/></div><div class="pv-card-actions pv-filter-end"><button class="wb-btn primary" @click="catId=null;cat.name='';cat.description='';catError='';catOpen=true"><Icon name="Plus"/>新建知识库</button></div></div><div class="pv-category-grid"><article v-for="c in filteredCats" :key="c.id" class="pv-card pv-category-card"><span class="pv-category-symbol"><Icon name="Reading"/></span><div class="pv-category-title"><h3>{{c.name}}</h3><el-dropdown trigger="click" @command="$event==='edit'?(catId=c.id,Object.assign(cat,copy(c)),catError='',catOpen=true):removeCategory(c.id)"><button class="wb-icon-button" :aria-label="`${c.name}操作`"><Icon name="MoreFilled"/></button><template #dropdown><el-dropdown-menu><el-dropdown-item command="edit">编辑知识库</el-dropdown-item><el-dropdown-item command="delete">删除空知识库</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div><p>{{c.description||'暂无说明'}}</p><div class="pv-category-bottom"><div><span>{{s.docs.value.filter(d=>d.categoryId===c.id).length}} 篇知识</span><button class="wb-text-button" @click="navigate('knowledge/documents',c.id)">查看知识 →</button></div><button class="wb-btn" @click="windowNewKnowledge(c.id)"><Icon name="Plus"/>新增知识</button></div></article><div v-if="!filteredCats.length" class="pv-empty"><strong>没有匹配的知识库</strong></div></div></section>
<div v-else class="pv-card"><div class="pv-filters"><div class="pv-search"><Icon name="Search"/><input v-model="search" placeholder="搜索知识标题或用途" aria-label="搜索知识"/></div><PreviewSelect v-model="category" aria-label="知识库筛选"><option value="">全部知识库</option><option v-for="c in s.categories.value" :key="c.id" :value="c.id">{{c.name}}</option></PreviewSelect><PreviewSelect v-model="status" aria-label="知识状态筛选"><option value="">全部状态</option><option>已发布</option><option>未生效</option><option>已过期</option><option>已停用</option></PreviewSelect><div class="pv-card-actions pv-filter-end"><button v-if="view!=='chunks'" class="wb-btn primary" @click="view==='categories'?(catId=null,cat.name='',cat.description='',catError='',catOpen=true):openDoc()"><Icon name="Plus"/>{{view==='categories'?'新建知识库':'新增知识'}}</button><button v-else class="wb-btn" @click="navigate('knowledge/recall')">召回测试 →</button></div></div>
<div v-if="view==='documents'" class="pv-table-scroll"><table class="pv-table"><thead><tr><th>知识标题 / 用途</th><th>所属知识库</th><th>状态 / 有效期</th><th>切片数</th><th>更新人 / 时间</th><th>操作</th></tr></thead><tbody><tr v-for="d in rows.slice((page-1)*8,page*8)" :key="d.id"><td class="pv-wide-cell"><strong>{{d.title}}</strong><small>{{d.purpose}}</small></td><td>{{catName(d.categoryId)}}</td><td><span class="pv-tag" :class="knowledgeStatus(d)==='已发布'?'green':''">{{knowledgeStatus(d)}}</span><small>{{d.end?`至 ${dateOf(d.end)}`:d.start?`${dateOf(d.start)} 起`:'长期有效'}}</small></td><td>{{d.chunks.length}}</td><td>{{d.author}}<small>{{dateOf(d.updatedAt)}}</small></td><td><div class="pv-row-actions"><button @click="openDoc(d)">查看 / 编辑</button><el-dropdown trigger="click" @command="$event==='restore'?restore(d):$event==='vector'?vector(d):(d.enabled=!d.enabled)"><button class="wb-text-button">更多 <Icon name="ArrowDown"/></button><template #dropdown><el-dropdown-menu><el-dropdown-item command="vector" :disabled="vectorBusy===d.id">更新检索内容</el-dropdown-item><el-dropdown-item command="toggle">{{d.enabled?'停用':'启用'}}</el-dropdown-item><el-dropdown-item command="restore" :disabled="!d.previous">恢复上一版</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></td></tr></tbody></table></div>
<div v-else class="pv-chunk-list"><article v-for="item in chunks.slice((page-1)*8,page*8)" :key="`${item.doc.id}-${item.index}`" class="pv-chunk-card"><div><span class="pv-tag">切片 {{item.index+1}}</span><strong>{{item.doc.title}}</strong><span class="pv-muted">{{catName(item.doc.categoryId)}} · {{item.text.length}} 字</span><span v-if="knowledgeStatus(item.doc)!=='已发布'" class="pv-tag">{{knowledgeStatus(item.doc)}}</span></div><p>{{item.text}}</p><button class="wb-text-button" @click="editChunk(item.doc,item.index)">编辑切片</button></article></div>
<div v-if="!count" class="pv-empty"><Icon name="Reading"/><strong>没有符合条件的知识</strong><span>可以调整筛选条件或新增知识</span></div><TableFooter v-model:page="page" :total="count"/></div></template>
<template v-else><PageHeading :title="editingId?'编辑客服知识':'新增客服知识'" show-title description="直接发布即可生效；离开页面时，未发布的编辑不会保留。" eyebrow="AI 与知识"/><div class="pv-editor-grid"><section class="pv-card pv-editor-settings"><h3>知识信息</h3><div class="pv-form"><label>所属知识库<PreviewSelect v-model="form.categoryId"><option v-for="c in s.categories.value" :key="c.id" :value="c.id">{{c.name}}</option></PreviewSelect></label><label>标题<input v-model="form.title" maxlength="100" placeholder="这篇内容能解决什么问题？"/></label><label v-if="editingId">用途说明<textarea v-model="form.purpose" rows="3" maxlength="500"/><small>解析后自动生成，可由客服修订</small></label><div class="pv-form-divider"></div><h3>分段设置</h3><label>分隔符<input v-model="form.separator" placeholder="\\n\\n"/><small>使用 \n 表示换行</small></label><div class="pv-form-grid"><label>分段长度<input v-model.number="form.length" type="number" min="100" max="4000" step="1"/></label><label>重叠长度<input v-model.number="form.overlap" type="number" min="0" step="1"/></label></div><button class="wb-btn primary-outline" @click="parse"><Icon name="Document"/>预览分段</button><small class="pv-muted">修改正文或分段设置后，请重新预览。</small><div class="pv-form-divider"></div><h3 class="pv-validity-heading">有效期 <span class="pv-muted">选填</span><el-tooltip content="可选择是否填写生效时间，不填则长期有效；已填写失效时间的内容到期后不再被检索" placement="top" trigger="click" :show-after="0" :hide-after="0" popper-class="pv-validity-help"><button class="pv-help" type="button" aria-label="有效期填写说明">?</button></el-tooltip></h3><label>生效时间<PreviewDatePicker v-model="form.start" type="datetime" aria-label="知识生效时间"/></label><label>失效时间<PreviewDatePicker v-model="form.end" type="datetime" aria-label="知识失效时间"/></label><div class="pv-retrieval-summary">全店检索：Top K {{s.retrieval.topK}} · Score {{s.retrieval.score}}<button class="wb-text-button" @click="navigate('settings/retrieval')">去设置</button></div></div></section>
<div class="pv-editor-main"><div class="pv-upload-area" :class="{dragging}" @dragover.prevent="dragging=true" @dragleave.prevent="dragging=false" @drop.prevent="dropped"><Icon name="UploadFilled"/><p>拖拽文件至此，或者 <button class="wb-text-button" @click="upload?.click()">选择本地文件</button></p><small>MD、TXT、CSV、TSV、JSON、YAML、XML、LOG · UTF-8 编码 · 单个文件不超过 2 MB</small><span v-if="uploadedName" class="pv-uploaded-file">{{uploadedName}}</span><input ref="upload" type="file" accept=".md,.markdown,.txt,.csv,.tsv,.json,.yaml,.yml,.xml,.log" hidden @change="fileSelected"/></div><section class="pv-card pv-editor-content"><div class="pv-tabs"><button :class="{active:tab==='content'}" @click="tab='content'">知识正文</button><button :class="{active:tab==='preview'}" @click="tab='preview'">分段预览 <span v-if="preview">{{preview.length}}</span></button><button v-if="editingId" :class="{active:tab==='published'}" @click="tab='published'">已发布切片</button><div class="pv-card-actions pv-editor-card-actions"><button class="wb-btn" :disabled="publishing" @click="editor=false">返回列表</button><button class="wb-btn primary" :disabled="publishing" @click="publish"><Icon v-if="publishing" name="Loading" spin/>{{publishing?'正在发布':'发布生效'}}</button></div></div><textarea v-if="tab==='content'" v-model="form.content" class="pv-content-textarea" placeholder="填写客服知识，或从上方上传纯文本文件。" aria-label="知识正文"/><div v-else class="pv-editor-chunks"><template v-if="tab==='preview'&&preview"><article v-for="(text,i) in preview" :key="i" class="pv-chunk-card"><div><span class="pv-tag">切片 {{i+1}}</span><span class="pv-muted">{{text.length}} 字</span></div><p>{{text}}</p></article></template><template v-else-if="tab==='published'"><article v-for="(text,i) in s.docs.value.find(d=>d.id===editingId)?.chunks" :key="i" class="pv-chunk-card"><div><span class="pv-tag">切片 {{i+1}}</span></div><p>{{text}}</p><button class="wb-text-button" @click="editChunk(s.docs.value.find(d=>d.id===editingId)!,i)">编辑已发布切片</button></article></template><div v-else class="pv-empty"><Icon name="Document"/><strong>还没有当前内容的分段预览</strong><span>点击左侧「预览分段」查看效果</span></div></div></section></div></div><p v-if="error" class="wb-form-error" role="alert">{{error}}</p></template>
<el-dialog v-model="catOpen" :title="catId?'编辑知识库':'新建知识库'" width="500px" class="wb-dialog" align-center><form id="pv-category-form" class="pv-form" @submit.prevent="saveCategory"><label>知识库名称<input v-model="cat.name" maxlength="50" required/></label><label>用途描述<textarea v-model="cat.description" rows="3" maxlength="300" placeholder="例如：与退货、换货、退款有关的客服办理指引"/></label><p v-if="catError" class="wb-form-error" role="alert">{{catError}}</p></form><template #footer><button class="wb-btn" @click="catOpen=false">取消</button><button class="wb-btn primary" type="submit" form="pv-category-form">保存</button></template></el-dialog>
<el-dialog v-model="chunkOpen" title="编辑知识切片" width="680px" class="wb-dialog" align-center><div class="pv-form"><p class="pv-muted">保存后同步更新文章内的已发布切片与召回测试内容。</p><textarea v-model="chunkText" rows="10" aria-label="切片内容"/><p v-if="chunkError" class="wb-form-error" role="alert">{{chunkError}}</p></div><template #footer><button class="wb-btn" @click="chunkOpen=false">取消</button><button class="wb-btn primary" @click="saveChunk">保存切片</button></template></el-dialog>
</div></template>
